-- Designed receipt e-mail (task-10-6, subject and wish line task-20-6): HTML and plain text from emails/eingangsbestaetigung.*,
-- generated by emails/build_receipt_migration.py. Customer input is HTML-escaped in the HTML part.
-- {{customer_number_note}}: customer number only for requests already linked to a customer (task-15-3).

alter table public.messages add column if not exists body_html text;
comment on column public.messages.body_html is 'Optional HTML part of an outgoing message; body_text stays the plain-text part and the dashboard view.';

create or replace function private.html_escape(value text) returns text
language sql immutable set search_path = '' as $$
  select replace(replace(replace(replace(replace(coalesce(value, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;'), '"', '&quot;'), '''', '&#39;')
$$;

create or replace function private.receipt_service_label(kind public.service_kind) returns text
language sql immutable set search_path = '' as $$
  select case kind when 'inspection' then 'Inspektion' when 'scheduled_maintenance' then 'Planmäßige Wartung' else 'Diagnose und Reparatur' end
$$;

-- Wish line (task-20-6): the held window with "vorgemerkt, noch nicht bestätigt", otherwise date and wished time.
-- ingest_submission queues the receipt after the hold, so the hold is already there.
create or replace function private.receipt_wish(req public.requests) returns text
language sql stable set search_path = '' as $$
  select coalesce(
    (select to_char(h.starts_at at time zone 'Europe/Berlin', 'DD.MM.YYYY, HH24:MI') || '–' || to_char(h.ends_at at time zone 'Europe/Berlin', 'HH24:MI')
       || ' Uhr (vorgemerkt, noch nicht bestätigt)'
     from public.visit_holds h where h.request_id = req.id and h.status = 'open' order by h.created_at desc limit 1),
    to_char(req.requested_visit_date, 'DD.MM.YYYY') || coalesce(case
      when req.raw_payload -> 'request' ->> 'preferred_time' = 'morning' then ', vormittags'
      when req.raw_payload -> 'request' ->> 'preferred_time' = 'afternoon' then ', nachmittags'
      when req.raw_payload -> 'request' ->> 'preferred_time' ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then ', ab ' || (req.raw_payload -> 'request' ->> 'preferred_time') || ' Uhr'
    end, ''),
    'keine Angabe')
$$;

create or replace function private.receipt_text(req public.requests) returns text
language sql stable set search_path = '' as $f$
  with t(template) as (select $tpl$RHEINWERK INDUSTRIESERVICE · EINGANGSBESTÄTIGUNG

Guten Tag {{contact_name}},

vielen Dank für Ihre Serviceanfrage. Sie ist bei uns eingegangen
und hat die Nummer {{request_number}}.

  ANFRAGENUMMER: {{request_number}}

IHRE ANGABEN
- Unternehmen:  {{company_name}}
- Standort:     {{street}}, {{postal_code}} {{city}}
- Leistung:     {{service_kind}}
- Wunschtermin: {{preferred_date}}

SO GEHT ES WEITER
1. Unser Service Desk prüft die Anfrage.
2. Sie erhalten die verbindliche Terminbestätigung in einer
   eigenen E-Mail, oder wir melden uns mit Rückfragen.

Mit dieser E-Mail ist noch kein Auftrag erteilt und noch kein
Termin zugesagt. Ein vorgemerkter Wunschtermin wird erst mit der
Terminbestätigung verbindlich; Priorität und Konditionen klären
wir nach der Prüfung.

WICHTIG: Bei Produktionsstillstand oder Sicherheitsgefahr rufen
Sie uns bitte zusätzlich an: +49 621 00000-0

Antworten Sie bei Fragen einfach auf diese E-Mail oder nennen Sie
die Nummer {{request_number}} im Betreff.

{{customer_number_note}}Mit freundlichen Grüßen
RheinWerk Industrieservice · Service Desk

--
RheinWerk Industrieservice GmbH
Rheinwerkstraße 12, 68169 Mannheim
Telefon +49 621 00000-0
rheinwerk.industrieservice@gmail.com
Service Desk Mo–Fr 07:00–18:00.
Ohne gesetzliche Feiertage in Baden-Württemberg.

Diese E-Mail wurde automatisch versendet.
Fiktives Portfolio-Projekt. RheinWerk Industrieservice GmbH ist
kein reales Unternehmen.

$tpl$::text)
  select replace(replace(replace(replace(replace(replace(replace(replace(replace(template,
    '{{request_number}}', coalesce(req.request_number)),
    '{{contact_name}}', coalesce(req.contact_name)),
    '{{company_name}}', coalesce(req.company_name)),
    '{{street}}', coalesce(req.street_house_number)),
    '{{postal_code}}', coalesce(req.postal_code)),
    '{{city}}', coalesce(req.city)),
    '{{service_kind}}', coalesce(private.receipt_service_label(req.service_kind))),
    '{{preferred_date}}', coalesce(private.receipt_wish(req))),
    '{{customer_number_note}}', private.customer_number_note_text(req.customer_number)) from t
$f$;

